mapper.select:
SELECT q.* FROM edu_question q


        AND q.question_subject = #{query.subject}


        AND q.question_grade_level = #{query.gradeLevel}


        AND q.question_grade = #{query.grade}


        AND q.question_type = #{query.type}


        AND q.question_difficulty = #{query.difficulty}


        AND q.question_knowledge_point_ids LIKE CONCAT('%', #{query.knowledgePointIds}, '%')


        AND q.question_audit_status = #{query.auditStatus}



            AND q.question_status = #{query.status}


            AND q.question_status != 0




            AND (q.question_owner_user_id IS NULL OR q.question_owner_user_id = #{scope.ownerPredicate})




ORDER BY

    q.question_add_count
    q.question_use_count
    q.question_difficulty
    q.create_time


    ASC
    DESC

, q.question_id DESC

SELECT COUNT(*) FROM edu_question
WHERE question_stem = #{stem}
  AND question_subject = #{subject}
  AND question_status = 1

    AND (question_owner_user_id = #{ownerUserId} OR question_owner_user_id IS NULL)

mapper.update:
UPDATE edu_question
SET question_add_count = COALESCE(question_add_count, 0) + 1
WHERE question_id = #{questionId}

mapper.select:
SELECT q.* FROM edu_question q

    q.question_subject = #{subject}
    AND q.question_status = 1

        AND q.question_grade_level = #{gradeLevel}



            AND (q.question_owner_user_id IS NULL OR q.question_owner_user_id = #{scope.ownerPredicate})



ORDER BY q.question_id DESC
LIMIT #{limit}
